/** Legacy zero SPO wildcards must mean the same thing in planning, scanning and counting. */
class LmdbLegacyZeroWildcardTest {
	@TempDir
	Path directory;

	@ParameterizedTest
	@ValueSource(strings = { "spoc,posc", "cspo,sopc" })
	void zeroPatternsAgreeAcrossReadApisAndReopen(String orders) throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig(orders);
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			store.startTransaction();
			for (boolean explicit : new boolean[] { true, false }) {
				for (long[] quad : new long[][] { { 10, 20, 30, 0 }, { 10, 21, 31, 7 },
						{ 11, 20, Long.MIN_VALUE + 128, 0 }, { 12, 20, 32, 7 }, { 10, 20, 30, 7 } }) {
					store.storeTriple(quad[0], quad[1], quad[2], quad[3], explicit);
				}
			}
			store.commit();
			assertReadApis(store);
		}
		try (TripleStore store = new TripleStore(directory.toFile(), config, null)) {
			assertReadApis(store);
		}
	}

	private static void assertReadApis(TripleStore store) throws Exception {
		try (Txn txn = store.getTxnManager().createReadTxn()) {
			for (boolean explicit : new boolean[] { true, false }) {
				for (long context : new long[] { -1, 0, 7 }) {
					for (int mask = 0; mask < 8; mask++) {
						long[] canonical = { (mask & 1) == 0 ? -1 : 10, (mask & 2) == 0 ? -1 : 20,
								(mask & 4) == 0 ? -1 : 30 };
						long[] zero = Arrays.stream(canonical).map(id -> id == -1 ? 0 : id).toArray();
						List<List<Long>> expected = rows(
								store.getTriples(txn, canonical[0], canonical[1], canonical[2], context, explicit));
						assertThat(rows(store.getTriples(txn, zero[0], zero[1], zero[2], context, explicit)))
								.as("mask=%s context=%s explicit=%s", mask, context, explicit)
								.containsExactlyInAnyOrderElementsOf(expected);
						assertThat(store.hasTriples(txn, zero[0], zero[1], zero[2], context, explicit))
								.isEqualTo(!expected.isEmpty());
						assertThat(store.countTriples(txn, zero[0], zero[1], zero[2], context, explicit))
								.isEqualTo(expected.size());
						assertThat(store.cardinality(zero[0], zero[1], zero[2], context))
								.isEqualTo(2.0 * expected.size());
						String index = store.getIndexName(txn, canonical[0], canonical[1], canonical[2], context);
						assertThat(store.getIndexName(txn, zero[0], zero[1], zero[2], context)).isEqualTo(index);
						assertThat(store.getSupportedOrders(txn, zero[0], zero[1], zero[2], context))
								.isEqualTo(store.getSupportedOrders(txn, canonical[0], canonical[1], canonical[2],
										context));
						for (StatementOrder order : store.getSupportedOrders(txn, canonical[0], canonical[1],
								canonical[2], context)) {
							assertThat(rows(store.getTriples(txn, order, zero[0], zero[1], zero[2], context, explicit)))
									.isEqualTo(rows(store.getTriples(txn, order, canonical[0], canonical[1],
											canonical[2], context, explicit)));
						}
						assertThat(rows(store.getTriplesRange(txn, zero[0], zero[1], zero[2], context, explicit,
								new LmdbKeyRange(null, null, index))))
										.containsExactlyInAnyOrderElementsOf(expected);
						TripleStore.PreparedIndexCount canonicalCount = store.prepareExactIndexCount(txn, canonical[0],
								canonical[1], canonical[2], context, explicit);
						TripleStore.PreparedIndexCount zeroCount = store.prepareExactIndexCount(txn, zero[0], zero[1],
								zero[2], context, explicit);
						assertThat(zeroCount == null).isEqualTo(canonicalCount == null);
						if (zeroCount != null) {
							assertThat(zeroCount.execute()).hasValue(expected.size());
						}
						LmdbRecordIterator retained = store.getTriplesRetained(txn, zero[0], zero[1], zero[2], context,
								explicit);
						try {
							assertThat(rows(retained)).containsExactlyInAnyOrderElementsOf(expected);
							store.resetTriples(retained, zero[0], zero[1], zero[2], context, explicit);
							assertThat(retained.getSourceRowsScannedActual()).isZero();
							assertThat(rows(retained)).containsExactlyInAnyOrderElementsOf(expected);
						} finally {
							retained.dispose();
						}
					}
				}
				assertThat(rows(store.getTriples(txn, 0, 0, Long.MIN_VALUE + 128, 0, explicit)))
						.containsExactly(List.of(11L, 20L, Long.MIN_VALUE + 128, 0L));
				assertThat(rows(store.getTriples(txn, 0, 0, 0, 0, explicit))).hasSize(2);
				assertThat(prefixRows(store, txn, 0, explicit)).isEqualTo(prefixRows(store, txn, -1, explicit));
				assertThat(store.planRootSplitKeys(txn, 0, 0, 0, -1, explicit, 3)).usingRecursiveComparison()
						.isEqualTo(store.planRootSplitKeys(txn, -1, -1, -1, -1, explicit, 3));
			}
		}
	}

	private static List<List<Long>> prefixRows(TripleStore store, Txn txn, long wildcard, boolean explicit)
			throws Exception {
		LmdbPrefixRunPlan plan = store.prefixRunPlan(txn, new int[] { TripleIndex.PRED_IDX }, wildcard, wildcard,
				wildcard, -1);
		assertThat(plan).isNotNull();
		List<List<Long>> result = new ArrayList<>();
		try (LmdbPrefixRunCursor cursor = store.getPrefixRuns(txn, plan, wildcard, wildcard, wildcard, -1, explicit,
				true)) {
			while (cursor.next()) {
				result.add(List.of(cursor.prefixValue(TripleIndex.PRED_IDX), cursor.runRowCount()));
			}
		}
		return result;
	}

	private static List<List<Long>> rows(RecordIterator iterator) {
		try (iterator) {
			List<List<Long>> result = new ArrayList<>();
			long[] quad;
			while ((quad = iterator.next()) != null) {
				result.add(List.of(quad[0], quad[1], quad[2], quad[3]));
			}
			return result;
		}
	}
}
